from pathlib import Path
p=Path('app/components.tsx');s=p.read_text(encoding='utf-8').replace('export function Header(){','export function Header({current="home"}:{current?:string}){').replace('href="/" aria-current="page"','href="/" aria-current={current==="home"?"page":undefined}').replace('href="/gallery">Catalogue','href="/gallery" aria-current={current==="gallery"?"page":undefined}>Catalogue').replace('href="/gallery?view=custom-work">Custom work','href="/gallery?view=custom-work" aria-current={current==="custom"?"page":undefined}>Custom work');p.write_text(s,encoding='utf-8')
p=Path('app/gallery/page.tsx');s=p.read_text(encoding='utf-8').replace('<Header/>','<Header current={initial.view==="custom-work"?"custom":"gallery"}/>');p.write_text(s,encoding='utf-8')
for name,target in [('catalogue','/gallery'),('services','/gallery?view=custom-work')]:
 Path('public/preview/'+name+'.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Opening catalogue</title><p><a href="'+target+'">Open catalogue</a></p><script>const target=new URL("'+target+'",location.origin);new URLSearchParams(location.search).forEach((v,k)=>{if(k!=="theme")target.searchParams.set(k,v)});location.replace(target.href)</script></html>',encoding='utf-8')
